import{_ as a,o as t,c as r,a7 as s}from"./chunks/framework.FWlv_suP.js";const h=JSON.parse('{"title":"Vault Nest Terms and Conditions","description":"Standalone Terms and Conditions for Vault Nest.","frontmatter":{"title":"Vault Nest Terms and Conditions","description":"Standalone Terms and Conditions for Vault Nest.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"terms/vault-nest.md","filePath":"terms/vault-nest.md"}'),o={name:"terms/vault-nest.md"};function i(n,e,l,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="terms-and-conditions-for-vault-nest" tabindex="-1">Terms and Conditions for Vault Nest <a class="header-anchor" href="#terms-and-conditions-for-vault-nest" aria-label="Permalink to &quot;Terms and Conditions for Vault Nest&quot;">​</a></h1><p><strong>Effective Date:</strong> August 1, 2026</p><h2 id="use-of-vault-nest" tabindex="-1">Use of Vault Nest <a class="header-anchor" href="#use-of-vault-nest" aria-label="Permalink to &quot;Use of Vault Nest&quot;">​</a></h2><p>Vault Nest is provided as a local password and sensitive-information management tool. You are responsible for the information you store, the strength and confidentiality of your master password, and lawful use of the app.</p><p>Do not use Vault Nest to store or share information you do not have the right to possess, or to support unlawful access or activity.</p><h2 id="master-password-and-recovery" tabindex="-1">Master Password and Recovery <a class="header-anchor" href="#master-password-and-recovery" aria-label="Permalink to &quot;Master Password and Recovery&quot;">​</a></h2><p>Vault Nest does not operate an account or password-recovery service. If you lose your master password, your encrypted vault may become permanently inaccessible. The developer cannot decrypt or recover it.</p><p>Optional four-character easy login is less secure than the full master password. Optional failed-attempt limits can permanently delete the local vault when reached. Enable these features only after reviewing their warnings.</p><h2 id="security-responsibilities" tabindex="-1">Security Responsibilities <a class="header-anchor" href="#security-responsibilities" aria-label="Permalink to &quot;Security Responsibilities&quot;">​</a></h2><p>No security system can guarantee complete protection. Keep Android and Vault Nest updated, secure the device, use a unique master password, review copied or shared fields carefully, and do not expose secrets in support messages.</p><p>You are responsible for reviewing and removing sensitive values from the system clipboard and from any application used through Android&#39;s sharing features.</p><h2 id="backups-and-exports" tabindex="-1">Backups and Exports <a class="header-anchor" href="#backups-and-exports" aria-label="Permalink to &quot;Backups and Exports&quot;">​</a></h2><p>You are responsible for creating, testing, protecting, and retaining backups. Keep the backup passphrase and original master password safe; both may be needed after restoration.</p><p>Encrypted <code>.vaultpack</code> files remain sensitive. CSV exports are not encrypted and may contain readable credentials. Securely delete plaintext exports after their intended use.</p><h2 id="external-services" tabindex="-1">External Services <a class="header-anchor" href="#external-services" aria-label="Permalink to &quot;External Services&quot;">​</a></h2><p>Optional website-icon retrieval connects to website servers. Saving or sharing files through a third-party document provider or app is governed by that provider&#39;s terms and privacy practices.</p><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>Features, platform compatibility, and security behavior may change as Vault Nest is improved. The app is provided without a guarantee that it will always be available, error-free, or suitable for every security requirement.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions about these terms can be sent to <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',20)])])}const f=a(o,[["render",i]]);export{h as __pageData,f as default};
